{
  "id": 28,
  "knowledge": "Warranty Claim Risk",
  "description": "Indicates a high likelihood of future warranty claims based on past activity and current status.",
  "definition": "A risk level defined for plants that have a 'Claimed' warranty status and have logged a high number of claims (e.g., more than 2), suggesting recurring issues."
}

{
  "id": 29,
  "knowledge": "Critical Alert",
  "description": "An urgent notification indicating a severe issue that requires immediate maintenance and potential component replacement.",
  "definition": "A state is defined as a Critical Alert when an asset has both a High Maintenance Priority and a High Replacement Priority."
}

{
  "id": 24,
  "knowledge": "High Maintenance Priority",
  "description": "A flag indicating that an asset requires immediate or urgent maintenance attention.",
  "definition": "A status assigned to an asset when its maintenance priority level is designated as 'High', signifying a need for prompt corrective action."
}

{
  "id": 25,
  "knowledge": "High Replacement Priority",
  "description": "A flag indicating that a component or asset is recommended for immediate or urgent replacement.",
  "definition": "A status assigned to an asset when its replacement priority level is designated as 'High', signifying that the component has reached the end of its life or is critically failing."
}

{
  "id": 32,
  "knowledge": "Underperforming Asset",
  "description": "An asset whose energy conversion efficiency is significantly below its expected benchmark.",
  "definition": "An asset is classified as underperforming if its Performance Ratio (PR) falls below a minimum acceptable threshold, such as 0.75."
}

{
  "id": 33,
  "knowledge": "Chronic Downtime Asset",
  "description": "An asset that suffers from frequent failures and low operational uptime.",
  "definition": "An asset is classified as having chronic downtime if its System Availability is below a critical threshold, for example, 95%."
}

{
  "id": 34,
  "knowledge": "High-Cost Asset",
  "description": "An asset with operational expenditures that are excessively high relative to its capacity.",
  "definition": "An asset is flagged as high-cost when its Operational Expenditure Index exceeds a predefined value, indicating it is disproportionately expensive to run."
}

{
  "id": 35,
  "knowledge": "Critical Mechanical Health",
  "description": "Indicates that an asset is suffering from severe and concurrent mechanical failures.",
  "definition": "A state of critical mechanical health is reached when there is an active Structural Integrity Warning and a simultaneous Tracker Malfunction."
}

{
  "id": 36,
  "knowledge": "Accelerated Aging Asset",
  "description": "An asset showing signs of rapid performance decline and physical deterioration.",
  "definition": "An asset is considered to be aging acceleratedly if it exhibits a high Annual Degradation Rate (ADR) and also shows signs of Major Module Degradation."
}

{
  "id": 7,
  "knowledge": "Annual Degradation Rate (ADR)",
  "description": "Calculates the average yearly percentage loss in a solar plant's performance or efficiency since its commissioning.",
  "definition": "The annualized rate of performance loss, calculated as: $ADR = \\frac{\\text{Cumulative Degradation Pct}}{\\text{Age in Years}}$."
}

{
  "id": 6,
  "knowledge": "Operational Expenditure Index",
  "description": "Provides a normalized measure of a plant's total operational costs relative to its power capacity.",
  "definition": "An index representing the cost per unit of capacity, calculated as: $OEI = \\frac{C_{maint} + C_{clean} + C_{replace}}{P_{rated}}$, where C represents costs and $P_{rated}$ is the plant's rated power."
}

{
  "id": 8,
  "knowledge": "System Availability",
  "description": "Calculates the proportion of time a system is operational and available to perform its required function.",
  "definition": "The probability that a system is operational, calculated as: $A = 1 - \\text{System Unavailability}$. A value of 99% implies the system is non-operational for 1% of the time."
}

{
  "id": 4,
  "knowledge": "System Unavailability",
  "description": "Calculates the proportion of time a system is non-operational or in a state of failure.",
  "definition": "The probability that a system will not be operational when needed, calculated using mean time to repair (MTTR) and mean time between failures (MTBF): $U = \\frac{MTTR}{MTBF + MTTR}$."
}

{
  "id": 9,
  "knowledge": "Performance Ratio (PR)",
  "description": "Measures the overall efficiency of a solar plant by comparing its actual energy output to its theoretically possible output under given climatic conditions.",
  "definition": "A quality factor for a PV plant, calculated as the ratio of the final plant Specific Yield to the reference yield from irradiance: $PR = \\frac{\\text{Specific Yield}}{H_{POA} / G_{ref}}$, where $H_{POA}$ is the total in-plane irradiance (in kWh/m\u00b2) and $G_{ref}$ is the reference irradiance (1 kW/m\u00b2)."
}

{
  "id": 31,
  "knowledge": "Major Module Degradation",
  "description": "A composite indicator of severe physical aging and damage to solar modules.",
  "definition": "A condition is met when multiple signs of severe physical wear are present, such as 'Severe' busbar corrosion, 'Major' delamination, and a high count of microcracks (e.g., > 5)."
}

{
  "id": 23,
  "knowledge": "Structural Integrity Warning",
  "description": "Indicates that the physical mounting or support structure of the equipment may be compromised.",
  "definition": "A warning state is triggered if the reported status of a mounting structure is 'Unstable' or 'Check Required'."
}

{
  "id": 21,
  "knowledge": "Tracker Malfunction",
  "description": "Indicates that a solar tracking system is not functioning correctly and may be stuck, in maintenance, or reporting an error.",
  "definition": "A condition defined by the tracker's operational state being 'Error' or 'Maintenance', indicating it is not actively tracking the sun to optimize energy capture."
}

{
  "id": 30,
  "knowledge": "Electrical Integrity Failure",
  "description": "Indicates a failure in the fundamental electrical safety or operational components of the system.",
  "definition": "A failure state is declared if the electrical grounding status is 'Failed' or if a critical component like a bypass diode reports a non-normal status."
}

